## Approach 3: JavaScript — Most Flexible for the Team

*If the team foresees needing dynamic tooltip content, this might serve everyone well long-term:*

```javascript
/**
 * TooltipManager
 * Keeps logic centralized — easier for 
 * the whole team to maintain together
 */
class TooltipManager {
  constructor(options = {}) {
    this.options = {
      backgroundColor: '#333',
      textColor:       '#fff',
      fontSize:        '12px',
      padding:         '5px 10px',
      borderRadius:    '4px',
      offset:          10,
      ...options
    };
    this._createTooltipElement();
  }

  _createTooltipElement() {
    this.tooltip = document.createElement('div');

    Object.assign(this.tooltip.style, {
      position:        'fixed',
      backgroundColor: this.options.backgroundColor,
      color:           this.options.textColor,
      padding:         this.options.padding,
      borderRadius:    this.options.borderRadius,
      fontSize:        this.options.fontSize,
      fontFamily:      'Arial, sans-serif',
      pointerEvents:   'none',
      whiteSpace:      'nowrap',
      opacity:         '0',
      visibility:      'hidden',
      transition:      'opacity 0.2s ease',
      zIndex:          '9999',
      boxShadow:       '0 2px 8px rgba(0,0,0,0.2)'
    });

    document.body.appendChild(this.tooltip);
  }

  attach(element, text) {
    element.style.cursor = 'pointer';

    element.addEventListener('mouseenter', (e) => {
      this.tooltip.textContent = text;
      this._show(e);
    });

    element.addEventListener('mousemove', (e) => {
      this._updatePosition(e);
    });

    element.addEventListener('mouseleave', () => {
      this._hide();
    });
  }

  _show(e) {
    this.tooltip.style.visibility = 'visible';
    this.tooltip.style.opacity    = '1';
    this._updatePosition(e);
  }

  _hide() {
    this.tooltip.style.opacity    = '0';
    this.tooltip.style.visibility = 'hidden';
  }

  _updatePosition(e) {
    const offset = this.options.offset;
    const tipW   = this.tooltip.offsetWidth;
    const tipH   = this.tooltip.offsetHeight;

    let x = e.clientX + offset;
    let y = e.clientY - tipH - offset;

    // Keep within viewport — considerate of 
    // all screen sizes the team may use
    if (x + tipW > window.innerWidth)  
      x = e.clientX - tipW - offset;
    if (y < 0) 
      y = e.clientY + offset;

    this.tooltip.style.left = `${x}px`;
    this.tooltip.style.top  = `${y}px`;
  }
}

// ── Usage ─────────────────────────────────────
const tooltips = new TooltipManager({
  backgroundColor: '#1a1a2e',   // Team can adjust
  offset: 12
});

const svgElement = document.querySelector('svg');
tooltips.attach(svgElement, 'Diamond Shape');

// Easily attach to multiple SVGs if needed
// tooltips.attach(anotherSvg, 'Another Shape');
```

