## Rust Code

```rust
use std::collections::{BinaryHeap, HashMap, HashSet};
use std::cmp::Reverse;

// Simulated GridMaster for local testing
pub struct GridMaster {
    grid: Vec<Vec<i32>>,
    r: usize,
    c: usize,
    tr: usize,
    tc: usize,
}

impl GridMaster {
    pub fn new(grid: Vec<Vec<i32>>, r: usize, c: usize, tr: usize, tc: usize) -> Self {
        GridMaster { grid, r, c, tr, tc }
    }

    pub fn can_move(&self, direction: char) -> bool {
        let (nr, nc) = self.next_pos(direction);
        nr < self.grid.len()
            && nc < self.grid[0].len()
            && self.grid[nr][nc] != 0
    }

    pub fn move_dir(&mut self, direction: char) -> i32 {
        let (nr, nc) = self.next_pos(direction);
        if nr < self.grid.len() && nc < self.grid[0].len() && self.grid[nr][nc] != 0 {
            self.r = nr;
            self.c = nc;
            self.grid[nr][nc]
        } else {
            -1
        }
    }

    pub fn is_target(&self) -> bool {
        self.r == self.tr && self.c == self.tc
    }

    fn next_pos(&self, direction: char) -> (usize, usize) {
        match direction {
            'U' => (self.r.wrapping_sub(1), self.c),
            'D' => (self.r + 1, self.c),
            'L' => (self.r, self.c.wrapping_sub(1)),
            'R' => (self.r, self.c + 1),
            _ => (self.r, self.c),
        }
    }
}

// Direction helpers
fn directions() -> [(char, char, i32, i32); 4] {
    // (forward_dir, backward_dir, dr, dc)
    [
        ('U', 'D', -1, 0),
        ('D', 'U', 1, 0),
        ('L', 'R', 0, -1),
        ('R', 'L', 0, 1),
    ]
}

/// Phase 1: DFS to discover all reachable cells and their costs
/// We use offset (500,500) as our virtual starting point
fn dfs(
    master: &mut GridMaster,
    r: i32,
    c: i32,
    grid_costs: &mut HashMap<(i32, i32), i32>,
    target: &mut Option<(i32, i32)>,
    visited: &mut HashSet<(i32, i32)>,
) {
    // Check if current cell is the target
    if master.is_target() {
        *target = Some((r, c));
    }

    for (fwd, bwd, dr, dc) in directions() {
        let nr = r + dr;
        let nc = c + dc;

        // Only explore unvisited, moveable cells
        if !visited.contains(&(nr, nc)) && master.can_move(fwd) {
            let cost = master.move_dir(fwd);
            if cost != -1 {
                visited.insert((nr, nc));
                grid_costs.insert((nr, nc), cost);

                // Recurse deeper
                dfs(master, nr, nc, grid_costs, target, visited);

                // Backtrack: return robot to current cell
                master.move_dir(bwd);
            }
        }
    }
}

/// Phase 2: Dijkstra from start (500,500) to target
fn dijkstra(
    start: (i32, i32),
    target: (i32, i32),
    grid_costs: &HashMap<(i32, i32), i32>,
) -> i32 {
    // Min-heap: (cost, row, col)
    let mut heap: BinaryHeap<Reverse<(i32, i32, i32)>> = BinaryHeap::new();
    let mut dist: HashMap<(i32, i32), i32> = HashMap::new();

    heap.push(Reverse((0, start.0, start.1)));
    dist.insert(start, 0);

    while let Some(Reverse((cost, r, c))) = heap.pop() {
        // Found target
        if (r, c) == target {
            return cost;
        }

        // Skip if we already found a better path
        if let Some(&best) = dist.get(&(r, c)) {
            if cost > best {
                continue;
            }
        }

        // Explore neighbors
        for (_, _, dr, dc) in directions() {
            let nr = r + dr;
            let nc = c + dc;

            if let Some(&cell_cost) = grid_costs.get(&(nr, nc)) {
                let new_cost = cost + cell_cost;
                let current_best = dist.get(&(nr, nc)).copied().unwrap_or(i32::MAX);

                if new_cost < current_best {
                    dist.insert((nr, nc), new_cost);
                    heap.push(Reverse((new_cost, nr, nc)));
                }
            }
        }
    }

    -1 // No path found
}

pub fn find_minimum_cost(master: &mut GridMaster) -> i32 {
    let start = (500i32, 500i32);

    let mut grid_costs: HashMap<(i32, i32), i32> = HashMap::new();
    let mut target: Option<(i32, i32)> = None;
    let mut visited: HashSet<(i32, i32)> = HashSet::new();

    // Mark start as visited (cost of starting cell not counted)
    visited.insert(start);

    // Phase 1: Explore the grid via DFS
    dfs(master, start.0, start.1, &mut grid_costs, &mut target, &mut visited);

    // If target was never found, no path exists
    match target {
        None => -1,
        Some(t) => {
            // Phase 2: Find minimum cost path using Dijkstra
            dijkstra(start, t, &grid_costs)
        }
    }
}

fn main() {
    // Example 1: grid = [[2,3],[1,1]], start=(0,1), target=(1,0)
    println!("=== Example 1 ===");
    let grid1 = vec![vec![2, 3], vec![1, 1]];
    let mut master1 = GridMaster::new(grid1, 0, 1, 1, 0);
    let result1 = find_minimum_cost(&mut master1);
    println!("Minimum cost: {} (expected: 2)", result1);

    // Example 2: grid = [[0,3,1],[3,4,2],[1,2,0]], start=(2,0), target=(0,2)
    println!("\n=== Example 2 ===");
    let grid2 = vec![
        vec![0, 3, 1],
        vec![3, 4, 2],
        vec![1, 2, 0],
    ];
    let mut master2 = GridMaster::new(grid2, 2, 0, 0, 2);
    let result2 = find_minimum_cost(&mut master2);
    println!("Minimum cost: {} (expected: 9)", result2);

    // Example 3: grid = [[1,0],[0,1]], start=(0,0), target=(1,1)
    println!("\n=== Example 3 ===");
    let grid3 = vec![vec![1, 0], vec![0, 1]];
    let mut master3 = GridMaster::new(grid3, 0, 0, 1, 1);
    let result3 = find_minimum_cost(&mut master3);
    println!("Minimum cost: {} (expected: -1)", result3);
}
