## C++ Implementation

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>

class Solution {
public:
    int subarraySum(std::vector<int>& nums, int k) {

        // Our collective "memory" of prefix sums seen so far
        // We initialize with {0: 1} to gracefully handle
        // subarrays that start from index 0
        std::unordered_map<int, int> prefixSumCount;
        prefixSumCount[0] = 1;

        int currentPrefixSum = 0;
        int totalCount = 0;

        for (int num : nums) {

            // Extend our prefix sum to include current element
            currentPrefixSum += num;

            // We gently ask: has (currentPrefixSum - k) appeared before?
            // If so, those occurrences represent valid subarrays ending here
            int complement = currentPrefixSum - k;

            if (prefixSumCount.find(complement) != prefixSumCount.end()) {
                totalCount += prefixSumCount[complement];
            }

            // Record this prefix sum for future reference
            prefixSumCount[currentPrefixSum]++;
        }

        return totalCount;
    }
};

// ── Demonstration ──────────────────────────────────────────
int main() {
    Solution solution;

    // Example 1: Expected output = 2
    std::vector<int> nums1 = {1, 1, 1};
    int k1 = 2;
    std::cout << "Example 1: " << solution.subarraySum(nums1, k1) << std::endl;

    // Example 2: Expected output = 2
    std::vector<int> nums2 = {1, 2, 3};
    int k2 = 3;
    std::cout << "Example 2: " << solution.subarraySum(nums2, k2) << std::endl;

    // Additional case with negative numbers
    std::vector<int> nums3 = {-1, -1, 1};
    int k3 = 0;
    std::cout << "Example 3: " << solution.subarraySum(nums3, k3) << std::endl;

    return 0;
}
