  console.log(`   Searching for    : "${searchElement}"`);
  console.log(`   Search type      : ${searchElementType}`);
  console.log(`   Array types found: [${arrayElementTypes.join(", ")}]`);
  console.log("--------------------------------------");

  // ---- Step 3: Kindly check for type harmony ----
  const hasTypeMatch = arrayElementTypes.includes(searchElementType);

  if (!hasTypeMatch) {
    console.log(
      `💡 A gentle observation: The search element type "${searchElementType}" ` +
      `does not align with the types in the array: [${arrayElementTypes.join(", ")}].`
    );
    console.log(
      `   Perhaps we might consider whether a type conversion would better ` +
      `serve our intentions?`
    );
  }

  // ---- Step 4: Strict search (respecting original types) ----
  const strictResult = array.includes(searchElement);

  // ---- Step 5: Flexible search (with type coercion, for consideration) ----
  const coercedResult = array.some(
    item => String(item) === String(searchElement)
  );

  // ---- Step 6: Count occurrences - acknowledging duplicates ----
  const occurrenceCount = array.filter(
    item => String(item) === String(searchElement)
  ).length;

  // ---- Step 7: Share findings with the group ----
  const result = {
    found_strict   : strictResult,
    found_coerced  : coercedResult,
    occurrences    : coercedResult ? occurrenceCount : 0,
    typeMismatch   : !hasTypeMatch,
    recommendation : !hasTypeMatch
      ? `Consider converting "${searchElement}" to a matching type before searching.`
      : "Types are aligned. No concerns to raise."
  };

  return result;
}


