package dao;

import model.User;
import util.DatabaseUtil;
import org.mindrot.jbcrypt.BCrypt; // team-approved security library

import java.sql.*;

/**
 * Data access layer - keeping database concerns here
 * so the rest of the team doesn't need to worry about them
 */
public class UserDAO {

    /**
     * Registers a new user - returns true if successful
     * The team may want to review the SQL structure together
     */
    public boolean registerUser(User user) {

        // Hashing password - our security-conscious colleagues
        // would be uncomfortable if we skipped this step
        String hashedPassword = BCrypt.hashpw(
            user.getPassword(), 
            BCrypt.gensalt(12)
        );

        String sql = 
            "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";

        try (
            Connection conn = DatabaseUtil.getConnection();
            PreparedStatement stmt = conn.prepareStatement(sql)
        ) {
            stmt.setString(1, user.getName());
            stmt.setString(2, user.getEmail());
            stmt.setString(3, hashedPassword);

            int rowsAffected = stmt.executeUpdate();
            return rowsAffected > 0;

        } catch (SQLException e) {
            // Worth bringing to the team's awareness
            System.err.println(
                "Registration concern: " + e.getMessage()
            );
            return false;
        }
    }

    /**
     * Checks if email already exists - to avoid any
     * awkward duplicate situations for users
     */
    public boolean isEmailExists(String email) {

        String sql = "SELECT COUNT(*) FROM users WHERE email = ?";

        try (
            Connection conn = DatabaseUtil.getConnection();
            PreparedStatement stmt = conn.prepareStatement(sql)
        ) {
            stmt.setString(1, email);
            ResultSet rs = stmt.executeQuery();

            if (rs.next()) {
                return rs.getInt(1) > 0;
            }

        } catch (SQLException e) {
            System.err.println(
                "Email check concern: " + e.getMessage()
            );
        }
        return false;
    }
}
