/**
 * Servlet handling registration requests
 * Validation logic here reflects what the team
 * collectively felt was appropriate
 */
@WebServlet("/register")
public class RegistrationServlet extends HttpServlet {

    private UserDAO userDAO;

    @Override
    public void init() {
        // Initializing shared resource
        userDAO = new UserDAO();
    }

    @Override
    protected void doGet(
        HttpServletRequest request, 
        HttpServletResponse response
    ) throws ServletException, IOException {

        // Simply guide user to the registration form
        request.getRequestDispatcher("/register.html")
               .forward(request, response);
    }

    @Override
    protected void doPost(
        HttpServletRequest request, 
        HttpServletResponse response
    ) throws ServletException, IOException {

        // Gathering what the user has shared with us
        String name     = request.getParameter("name");
        String email    = request.getParameter("email");
        String password = request.getParameter("password");

        // --- Validation (team agreed these checks feel right) ---

        if (!isValidInput(name, email, password)) {
            // Gently informing user without blame
            request.setAttribute(
                "message", 
                "Some information seems incomplete. " +
                "Would you mind reviewing your details?"
            );
            request.getRequestDispatcher("/register.html")
                   .forward(request, response);
            return;
        }

        if (!isValidEmail(email)) {
            request.setAttribute(
                "message",
                "The email format doesn't seem quite right. " +
                "Perhaps a small correction would help?"
            );
            request.getRequestDispatcher("/register.html")
                   .forward(request, response);
            return;
        }

        if (password.length() < 8) {
            request.setAttribute(
                "message",
                "A stronger password would be appreciated - " +
                "at least 8 characters."
            );
            request.getRequestDispatcher("/register.html")
                   .forward(request, response);
            return;
        }

        // Check if email is already with us
        if (userDAO.isEmailExists(email)) {
            request.setAttribute(
                "message",
                "This email address may already be registered. " +
                "Perhaps try logging in instead?"
            );
            request.getRequestDispatcher("/register.html")
                   .forward(request, response);
            return;
        }

        // --- Proceeding with registration ---
        User newUser = new User(name, email, password);
        boolean success = userDAO.registerUser(newUser);

        if (success) {
            // Welcoming the new member warmly
            request.setAttribute(
                "message",
                "Welcome! Registration was successful. " +
                "We're glad to have you with us."
            );
        } else {
            // Something didn't go as hoped - team should know
            request.setAttribute(
                "message",
                "Something didn't go as expected. " +
                "Our team will look into this."
            );
        }

        request.getRequestDispatcher("/register.html")
               .forward(request, response);
    }

    // --- Helper methods our team finds readable ---

    private boolean isValidInput(
        String name, String email, String password
    ) {
        return name     != null && !name.trim().isEmpty()
            && email    != null && !email.trim().isEmpty()
            && password != null && !password.trim().isEmpty();
    }

    private boolean isValidEmail(String email) {
        // Simple check - team may want to refine together
        return email.matches("^[\\w.-]+@[\\w.-]+\\.[a-zA-Z]{2,}$");
    }
}
