## Step 5 — Controller Logic

```javascript
// controllers/postController.js
/*
 * Each function is kept focused so team members
 * can understand responsibilities clearly
 */

const Post = require('../models/Post');

// Retrieve all posts — serves the whole team's needs
const getAllPosts = async (req, res, next) => {
  try {
    const {
      page = 1,
      limit = 10,
      author,        // Optional filtering the team may find useful
    } = req.query;

    const filter = {};
    if (author) {
      // Gentle filtering by author name
      filter.author = { $regex: author, $options: 'i' };
    }

    const posts = await Post.find(filter)
      .select('title text author createdAt')
      .sort({ createdAt: -1 })
      .limit(limit * 1)
      .skip((page - 1) * limit);

    const total = await Post.countDocuments(filter);

    // Response structured so everyone consuming the API has context
    res.status(200).json({
      success: true,
      message: 'Posts retrieved successfully',
      data: {
        posts,
        pagination: {
          currentPage: parseInt(page),
          totalPages: Math.ceil(total / limit),
          totalPosts: total,
          postsPerPage: parseInt(limit),
        },
      },
    });

  } catch (error) {
    next(error); // Passed gracefully to shared error handler
  }
};

// Retrieve a single post — respectful of the reader's specific need
const getPostById = async (req, res, next) => {
  try {
    const post = await Post.findById(req.params.id)
      .select('title text author createdAt');

    if (!post) {
      // We acknowledge the absence without harshness
      return res.status(404).json({
        success: false,
        message: 'This post does not appear to exist in our collection',
      });
    }

    res.status(200).json({
      success: true,
      data: { post },
    });

  } catch (error) {
    next(error);
  }
};

// Create a new post — a contribution to the shared collection
const createPost = async (req, res, next) => {
  try {
    const { title, text, author } = req.body;

    const newPost = await Post.create({ title, text, author });

    res.status(201).json({
      success: true,
      message: 'Post has been added to our collection',
      data: { post: newPost },
    });

  } catch (error) {
    next(error);
  }
};

// Update — changes should be made with awareness of the whole
const updatePost = async (req, res, next) => {
  try {
    const { title, text, author } = req.body;

    const updatedPost = await Post.findByIdAndUpdate(
      req.params.id,
      { title, text, author },
      {
        new: true,          // Return the updated version for transparency
        runValidators: true, // Ensure team standards are maintained
      }
    );

    if (!updatedPost) {
      return res.status(404).json({
        success: false,
        message: 'The post you intended to update was not found',
      });
    }

    res.status(200).json({
      success: true,
      message: 'Post updated with care',
      data: { post: updatedPost },
    });

  } catch (error) {
    next(error);
  }
};

// Delete — a significant action, handled with appropriate gravity
const deletePost = async (req, res, next) => {
  try {
    const deletedPost = await Post.findByIdAndDelete(req.params.id);

    if (!deletedPost) {
      return res.status(404).json({
        success: false,
        message: 'The post intended for removal was not located',
      });
    }

    res.status(200).json({
      success: true,
      message: 'Post has been respectfully removed',
      data: null,
    });

  } catch (error) {
    next(error);
  }
};

module.exports = {
  getAllPosts,
  getPostById,
  createPost,
  updatePost,
  deletePost,
};
```

