## Step 7 — Shared Error Handler

```javascript
// middleware/errorHandler.js
/*
 * A centralized place for errors, so no one team member
 * bears that responsibility alone
 */

const errorHandler = (err, req, res, next) => {
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Something went unexpectedly';

  // Mongoose validation — communicated constructively
  if (err.name === 'ValidationError') {
    statusCode = 400;
    const fields = Object.values(err.errors).map((e) => e.message);
    message = `Some fields need attention: ${fields.join(', ')}`;
  }

  // Invalid ID format — noted gently
  if (err.name === 'CastError') {
    statusCode = 400;
    message = 'The provided ID format was not recognized';
  }

  // Duplicate entry — handled without blame
  if (err.code === 11000) {
    statusCode = 400;
    message = 'It appears this entry already exists in our collection';
  }

  res.status(statusCode).json({
    success: false,
    message,
    // Stack shown only in development — not for external visibility
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
};

module.exports = errorHandler;
```

